import numpy as np, loader, json
emb=loader.load('model.language_model.embed_tokens.weight')
norm=loader.load('model.language_model.norm.weight')
v=json.load(open('/workspace/model/vocab.json'))
ex=[json.loads(l) for l in open('examples.jsonl')]
def logits(resid):
    r=resid.astype(np.float64); x=r/np.sqrt((r**2).mean()+1e-6)*norm
    return emb@x
P=np.load('/tmp/opencode/P.npy');W=np.load('/tmp/opencode/W.npy')
def tid(w):
    for cand in ('Ġ'+w,w):
        if cand in v: return v[cand]
    return None
tri=[]
for i in range(144):
    e=ex[i]; g=tid(e['swap'].split()[0]); c=tid(e['correct'].split()[0])
    if g is not None and c is not None and g!=c: tri.append((i,g,c))
rng=np.random.RandomState(0); idx=np.arange(len(tri)); rng.shuffle(idx)
tr=idx[:42]; te=idx[42:]
D=np.array([W[tri[i][0]]-P[tri[i][0]] for i in tr]); m=D.mean(0); mh=m/np.linalg.norm(m)
def win(X,mv,alpha,idxs):
    if alpha==0: Xe=X
    else:
        h=mv/np.linalg.norm(mv); Xe=X-alpha*np.outer(X@h,h)
    return sum(1 for i in idxs if (lambda lg: lg[tri[i][2]]>lg[tri[i][1]])(logits(Xe[tri[i][0]])))
print('TEST baseline correct>guess', win(W,np.zeros(1024),0,te),'/',len(te))
for a in [1,2,3,5]: print('remove m a=%s'%a, win(W,m,a,te), )
